+/**
+ * VTID-04223 AC-8: the recall-query unit test.
+ *
+ * `buildAgentRecallQuery()` (services/gateway/src/services/autopilot-agent/
+ * agent-memory-context.ts) is the text `dev_agent_memory` recall is embedded
+ * against at run start. The three things it must carry, and nothing more:
+ *
+ *   (a) the VTID, so memory rows tagged with the same task surface;
+ *   (b) the plan's first heading (the task sentence, whitespace-collapsed),
+ *       which for an autopilot task IS the request the planner wrote;
+ *   (c) the prior failure text — but ONLY when a previous attempt on this
+ *       finding failed; a first attempt must not get an empty third line,
+ *       because the query is embedded verbatim and a stray blank part
+ *       dilutes the embedding.
+ *
+ * This suite is test-only (AC-8 of VTID-04223); the source it pins is
+ * unchanged by it. It deliberately mocks the two modules that hold network
+ * clients so the suite is a pure unit test of the pure renderer.
+ */
+jest.mock('../src/services/dev-autopilot-execute', () => ({ supa: jest.fn() }));
+jest.mock('../src/services/dev-agent-memory', () => ({ recallDevMemory: jest.fn(), writeDevMemory: jest.fn() }));
+
+import {
+  AGENT_RECALL_QUERY_MAX_CHARS,
+  buildAgentRecallQuery,
+} from '../src/services/autopilot-agent/agent-memory-context';
+
+const VTID = 'VTID-04239';
+const PLAN = [
+  '# Plan: bound the executor recall query',
+  '',
+  'The recall query must carry the VTID, the plan and the prior failure.',
+  '',
+  '## Steps',
+  '- clip the plan',
+  '- append the failure when present',
+].join('\n');
+
+describe('VTID-04223 AC-8 buildAgentRecallQuery', () => {
+  it('carries the VTID and the plan\'s first heading', () => {
+    const q = buildAgentRecallQuery({ vtid: VTID, planMarkdown: PLAN });
+    const lines = q.split('\n');
+    expect(lines[0]).toBe(VTID);
+    expect(q).toContain('# Plan: bound the executor recall query');
+    // The plan is collapsed to one line, so the heading survives but the
+    // markdown body does not reintroduce line breaks.
+    expect(lines).toHaveLength(2);
+    expect(lines[1]).toContain('## Steps');
+  });
+
+  it('appends the prior failure text when one is present', () => {
+    const q = buildAgentRecallQuery({ vtid: VTID, planMarkdown: PLAN, priorFailure: 'jest failed: 2 suites, TS2742' });
+    const lines = q.split('\n');
+    expect(lines).toHaveLength(3);
+    expect(lines[0]).toBe(VTID);
+    expect(lines[2]).toBe('jest failed: 2 suites, TS2742');
+    expect(q.endsWith('TS2742')).toBe(true);
+  });
+
+  it('omits the prior failure entirely when absent (undefined, null or empty)', () => {
+    const withoutFailure = buildAgentRecallQuery({ vtid: VTID, planMarkdown: PLAN });
+    for (const priorFailure of [undefined, null, '', '   '] as Array<string | null | undefined>) {
+      const q = buildAgentRecallQuery({ vtid: VTID, planMarkdown: PLAN, priorFailure });
+      expect(q).toBe(withoutFailure);
+      expect(q).not.toMatch(/\n\s*$/);
+      expect(q.split('\n')).toHaveLength(2);
+    }
+  });
+
+  it('collapses the plan\'s whitespace so the heading is the first plan text, and bounds the query', () => {
+    const q = buildAgentRecallQuery({ vtid: VTID, planMarkdown: '\n\n  #   Heading   with   spaces \n\n body \n' });
+    const lines = q.split('\n');
+    expect(lines[0]).toBe(VTID);
+    expect(lines[1]).toBe('# Heading with spaces body');
+    const padded = buildAgentRecallQuery({ vtid: VTID, planMarkdown: 'p'.repeat(5_000) });
+    const [, clippedPlan] = padded.split('\n');
+    expect(clippedPlan).toHaveLength(AGENT_RECALL_QUERY_MAX_CHARS + 1); // the cap plus the ellipsis
+    expect(clippedPlan.endsWith('…')).toBe(true);
+    expect(padded).toBe(`${VTID}\n${clippedPlan}`);
+  });
+});
